          <div>Registered: ${new Date(a.registered_at * 1000).toLocaleString()}</div>
        </div>
      </div>
    `).join('');
  } catch(err) {
    document.getElementById('agent-list').innerHTML = `<div class="card" style="text-align:center;grid-column:1/-1;color:var(--error)">Error: ${err.message}</div>`;
  }
}
loadAgents();
setInterval(loadAgents, 10000);
</script>
</body>
</html>
