      </div>
    `).join('');
  } catch(err) {
    document.getElementById('entry-list').innerHTML = `<div class="error">Error: ${err.message}</div>`;
  }
}
function escHTML(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
loadKnowledge();
setInterval(loadKnowledge, 15000);
</script>
</body>
</html>
